function getToolById(id) {
  return TOOLS.find(function (t) { return t.id === id; });
}

function getRelatedTools(category, excludeId, limit) {
  const n = limit || 3;
  return TOOLS.filter(function (t) {
    return t.category === category && t.id !== excludeId;
  }).slice(0, n);
}

window.DROIDXP_TOOLS = TOOLS;
window.getToolById = getToolById;
window.getRelatedTools = getRelatedTools;
